CHAPTERS[10]["debates"] = [
    ("칠십 인인가 칠십이 인인가", [
        ("E Ga", "10:1과 10:17의 파송된 사람 수는 사본에 따라 칠십과 칠십이로 갈린다. 에드워즈가 이 무리를 ‘칠십(이)’이라고 부르는 것도 이 불확실성을 반영한다. 두 수는 모두 상징적 의미를 지닐 수 있다. 창세기 10장의 민족 목록은 히브리어 본문에서 일흔 민족, 칠십인역에서 일흔두 민족을 헤아리므로, 이 파송은 모든 민족을 향한 선교를 내다보는 것으로 읽힐 수 있다. 모세를 도운 일흔 장로와 진영에서 예언한 엘닷과 메닷(민 11:16–29)을 합하면 일흔둘이 된다는 해석도 있다. 갈런드는 칠십이를 본문으로 택하고, 둘씩 보내는 방식이 사도행전의 선교로 이어진다고 설명한다. 에드워즈는 이 무리가 열두 제자와 구별되며, 열둘이 더 큰 권위를 받았다고 본다. 개역개정은 ‘칠십 인’으로 옮긴다."),
    ]),
    ("제사장과 레위인은 왜 지나쳤는가", [
        ("Ga", "제사장과 레위인이 강도 만난 자를 피하여 지나간 이유는 흔히 시체와의 접촉을 금한 정결 규정(레 21:1–3)에서 찾아져 왔다. 거의 죽은 사람을 만지면 부정해져 성전 직무를 수행하지 못한다는 것이다. 갈런드는 ‘내려가다가’라는 동사가 그들이 예루살렘에서 여리고로, 곧 성전 직무를 마치고 돌아가는 길이었음을 보여 주므로 정결 규정이 결정적인 이유가 될 수 없다고 본다. 그는 두 사람을 멈추게 한 것을 같은 냉담함으로 읽는다. 갈런드는 예루살렘의 제사장층이 유대 사회의 귀족층을 이루었다는 요세푸스의 기록을 들어, 비유가 사회의 상층과 종교 지도자들에 대한 기대를 뒤집는다고 설명한다. 그다음에 나타나는 이는 청중이 기대했을 평범한 이스라엘 사람 대신 원수로 여겨지던 사마리아인이다."),
    ]),
    ("선한 사마리아인의 비유는 알레고리인가", [
        ("Ga F G", "교회사에서 이 비유는 오랫동안 알레고리로 읽혔다. 아우구스티누스는 강도 만난 사람을 아담으로, 예루살렘을 낙원으로, 강도를 마귀로, 사마리아인을 그리스도로, 주막을 교회로 읽었다. 포트너도 이 비유를 복음을 예시하는 이야기로 강해해 이 전통에 가깝다. 갈런드는 이 비유를 ‘내 이웃이 누구니이까’라는 물음에 대한 대답으로 읽으며, 예수께서 질문을 ‘누가 강도 만난 자의 이웃이 되겠느냐’로 바꾸신다고 설명한다. 이웃은 사랑받을 자격을 따지는 대상이기보다 필요 앞에서 자비를 베푸는 사람이 되는 일이다. 그린은 이 이야기를 사마리아인과 유대인 사이의 장벽을 허무는 사건으로 읽는다. 기독론적 읽기와 윤리적 읽기는 서로를 배제하지 않을 수 있지만, 본문의 문맥은 ‘가서 너도 이와 같이 하라’(10:37)는 명령으로 끝나 윤리적 부름을 전면에 둔다."),
    ]),
    ("마르다와 마리아: 활동의 삶과 관상의 삶?", [
        ("Ga G", "중세 교회는 마르다와 마리아를 활동의 삶과 관상의 삶의 대표로 읽고, 마리아가 택한 ‘좋은 편’을 수도적 관상 생활의 우위로 해석하기도 했다. 갈런드는 이 이야기의 요점이 말씀을 듣는 일이 섬김의 방식을 결정한다는 데 있다고 보며, 섬김 자체를 낮추지 않는다. 마르다의 문제는 섬김 자체보다 많은 일로 인한 염려와 분주함에 있다. 갈런드는 또한 이 장면이 여성이 제자로서 스승의 발치에 앉는다는 점에서 당시 관습을 벗어난다고 설명한다. 마르다는 마리아가 여자의 본분을 벗어났다고 여겼지만 예수는 마리아의 선택을 지지하신다. 그린은 여행 단락의 첫 부분이 듣고 행하는 제자도를 다룬다는 점에서, 선한 사마리아인의 행함과 마리아의 들음이 짝을 이룬다고 읽는다."),
    ]),
]
